// GERADO por scripts/gerar-manuais.mts — não editar à mão. Fonte: docs/manuais/cadastros.md
export const html: string = "<h2 id=\"visão-geral\">Visão geral</h2>\n<p>Os cadastros que vinham do P2S agora também podem ser feitos no próprio sistema: clientes e fornecedores, produtos, eventos e feiras, e o plano de contas (centros e sub-centros). Quem é vendedor passa a ser marcado na Ficha do RH.</p>\n<p>As telas deste manual são do sistema real, em 23/11/2026, com cadastros fictícios (CLIENTE EXEMPLO e FUNCIONARIO EXEMPLO). Os formulários de produto e evento foram preenchidos só para a foto, sem salvar.</p>\n<div class=\"tabela\"><table>\n<thead>\n<tr>\n<th>Cadastro</th>\n<th>Onde fica</th>\n<th>Botão</th>\n<th>Chave contra duplicado</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Clientes e fornecedores</td>\n<td>Comercial → Parceiros</td>\n<td>+ Novo cliente / fornecedor</td>\n<td>CPF ou CNPJ</td>\n</tr>\n<tr>\n<td>Produtos e equipamentos</td>\n<td>Estoque → Produtos</td>\n<td>+ Novo produto</td>\n<td>Código (categoria.subcategoria.sequência) ou nome</td>\n</tr>\n<tr>\n<td>Eventos e feiras</td>\n<td>Comercial → Eventos e Feiras</td>\n<td>+ Novo evento</td>\n<td>Nome + data inicial</td>\n</tr>\n<tr>\n<td>Centros e sub-centros</td>\n<td>OP → Natureza &amp; Classificação Financeira</td>\n<td>+ Centro / + Sub-centro</td>\n<td>Código do centro ou do sub-centro</td>\n</tr>\n<tr>\n<td>Vendedor, cliente e fornecedor do funcionário</td>\n<td>RH → Ficha do Funcionário → Papéis comerciais</td>\n<td>Marcar a caixa</td>\n<td>CPF da ficha</td>\n</tr>\n</tbody></table></div>\n<h2 id=\"antes-e-depois-da-virada\">Antes e depois da virada</h2>\n<p>O P2S continua oficial até a virada da chave. Por isso a regra muda conforme a fase:</p>\n<ul>\n<li><strong>Antes da virada:</strong> já dá para cadastrar aqui. O cadastro nasce com origem <strong>SISTEMA</strong>. Se depois o mesmo cliente, produto ou evento for cadastrado no P2S, a sincronização <strong>adota</strong> o cadastro daqui (pela chave da tabela acima) em vez de criar outro. O cadastro mantém o mesmo número e passa a seguir o P2S.</li>\n<li><strong>Cadastros que vieram do P2S</strong> ficam só para leitura enquanto o P2S for oficial. Altere no P2S; a mudança chega aqui na sincronização das 11h e das 17h. A exceção é a carteira do vendedor, que pode mudar sempre.</li>\n<li><strong>Depois que todas as empresas congelarem o P2S:</strong> o sistema vira a origem de todos os cadastros. Tudo pode ser editado aqui e a sincronização de cadastros para.</li>\n<li><strong>Quando todas as empresas concluírem a virada:</strong> a ligação com o P2S desliga de vez. Qualquer tentativa de falar com o P2S avisa &quot;P2S desligado&quot; e as rotinas automáticas do P2S deixam de rodar.</li>\n</ul>\n<h2 id=\"clientes-e-fornecedores\">Clientes e fornecedores</h2>\n<blockquote>\n<p>O passo a passo completo, com o <strong>Ramo / serviço</strong> dos fornecedores (gráfica, engenharia, papelaria…), contatos e bloqueio, está no manual <strong>Clientes e fornecedores (Parceiros)</strong>.</p>\n</blockquote>\n<p><strong>Onde fica:</strong> Comercial → Parceiros, botão <strong>+ Novo cliente / fornecedor</strong>. Clicar num parceiro da lista abre o mesmo formulário para editar. O selo SISTEMA marca o cadastro feito aqui.</p>\n<p><span class=\"figura\"><img src=\"data:image/png;base64,\" alt=\"Comercial → Parceiros: a lista com o botão + Novo cliente / fornecedor\" loading=\"lazy\" /><span class=\"legenda\">Comercial → Parceiros: a lista com o botão + Novo cliente / fornecedor</span></span></p>\n<ol>\n<li><p><strong>Tipo:</strong> Pessoa jurídica ou Pessoa física, e os papéis (cliente, fornecedor, transportadora).</p>\n</li>\n<li><p><strong>CNPJ ou CPF:</strong> é a chave do cadastro. Se já existir um cadastro com o mesmo documento, o sistema não salva e mostra o nome e o código do que já existe.</p>\n</li>\n<li><p><strong>Buscar na Receita</strong> (pessoa jurídica): preenche razão social, nome fantasia, endereço e telefone pelo CNPJ. Confira antes de salvar.</p>\n</li>\n<li><p><strong>Endereço principal:</strong> ao digitar o CEP, logradouro, bairro, cidade e UF vêm sozinhos. É o endereço que sai na proposta, no contrato e na nota fiscal.</p>\n</li>\n<li><p><strong>Telefones e e-mails:</strong> o e-mail principal (ou o de um contato) é com o que o cliente entra no Portal do Cliente.</p>\n</li>\n<li><p><strong>Contatos e outros endereços</strong> (entrega, cobrança): botões <strong>+ Contato</strong> e <strong>+ Endereço</strong>.</p>\n</li>\n<li><p><strong>Situação:</strong> Ativo ou Bloqueado. Bloquear pede o motivo.\n<span class=\"figura\"><img src=\"data:image/png;base64,\" alt=\"Novo cliente: os dados vieram da Receita pelo CNPJ e o endereço pelo CEP\" loading=\"lazy\" /><span class=\"legenda\">Novo cliente: os dados vieram da Receita pelo CNPJ e o endereço pelo CEP</span></span></p>\n</li>\n<li><p><strong>Carteira do vendedor:</strong> o vendedor responsável pelo cliente. O vendedor só vê e atende os clientes da carteira dele; sem carteira, o cliente entra na carteira de quem fizer a primeira ficha.</p>\n</li>\n</ol>\n<p><strong>CNPJ ou CPF repetido:</strong> o sistema não salva e diz qual cadastro já usa o documento.</p>\n<p><span class=\"figura\"><img src=\"data:image/png;base64,\" alt=\"CNPJ já cadastrado: o sistema recusa e mostra o cadastro existente\" loading=\"lazy\" /><span class=\"legenda\">CNPJ já cadastrado: o sistema recusa e mostra o cadastro existente</span></span></p>\n<h2 id=\"produtos-e-equipamentos\">Produtos e equipamentos</h2>\n<p><strong>Onde fica:</strong> Estoque → Produtos, botão <strong>+ Novo produto</strong>.</p>\n<ul>\n<li><strong>Categoria e subcategoria:</strong> escolha da lista ou crie com <strong>+ Nova categoria…</strong> e <strong>+ Nova subcategoria…</strong> (no formato &quot;NN - NOME&quot;).</li>\n<li><strong>Código:</strong> segue o padrão do P2S, categoria.subcategoria.sequência (ex.: 11.02.0003). Deixe vazio para o sistema gerar o próximo da subcategoria.</li>\n<li><strong>Nome, unidade, marca e modelo:</strong> o nome é a outra chave contra duplicado.</li>\n<li><strong>Para locação / Para venda</strong>, e <strong>Em desuso</strong> (some das listas).</li>\n<li><strong>Controle:</strong> Por quantidade (saldo) ou Por patrimônio (cada peça com número e QR).</li>\n<li><strong>Dias de preparo e de retorno:</strong> prendem a agenda antes e depois da locação.</li>\n<li><strong>Valor de indenização:</strong> é o que se cobra no extravio. O custo de reposição fica ao lado.</li>\n<li><strong>Nota fiscal:</strong> NCM, origem da mercadoria e peso.</li>\n</ul>\n<p><span class=\"figura\"><img src=\"data:image/png;base64,\" alt=\"Novo produto: o código 01.01.0026 foi gerado pela subcategoria\" loading=\"lazy\" /><span class=\"legenda\">Novo produto: o código 01.01.0026 foi gerado pela subcategoria</span></span></p>\n<p>Saldos, patrimônios e kits continuam em Estoque → Equipamentos de Locação; o preço, em Locações → Tabelas de Preço.</p>\n<h3 id=\"três-telas-três-papéis\">Três telas, três papéis</h3>\n<div class=\"tabela\"><table>\n<thead>\n<tr>\n<th>Tela</th>\n<th>Para que serve</th>\n<th>Vale para reservar?</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Estoque → Produtos</td>\n<td>O catálogo: o que se aluga ou vende, com código, categoria e dados da nota</td>\n<td>É a lista que aparece no orçamento, na ficha e na OS</td>\n</tr>\n<tr>\n<td>Estoque → Equipamentos de Locação</td>\n<td>Quanto existe de cada produto, por quantidade ou por patrimônio</td>\n<td>Sim: a disponibilidade da reserva sai daqui</td>\n</tr>\n<tr>\n<td>Estoque → Controle de Estoque</td>\n<td>Ficha técnica (peso, consumo, medidas), simulador de videowall e acessórios sugeridos na Expedição</td>\n<td>Não</td>\n</tr>\n</tbody></table></div>\n<h3 id=\"ligar-o-controle-de-estoque-a-produtos\">Ligar o Controle de Estoque a Produtos</h3>\n<p><strong>Onde fica:</strong> Estoque → Controle de Estoque, aba <strong>🔗 Ligar a Produtos</strong>.</p>\n<p>Cada equipamento da ficha técnica deve apontar para o produto do catálogo. Assim o primeiro inventário parte de uma lista só, e a Expedição sugere os acessórios também para os itens que vêm da OS.</p>\n<ul>\n<li><strong>Sugestões:</strong> cada equipamento mostra até 3 produtos de nome parecido, com a nota de semelhança. Verde (80% ou mais) costuma ser o mesmo item; confira os amarelos.</li>\n<li><strong>Ligar sugestões fortes:</strong> liga de uma vez os que têm sugestão de 80% ou mais sem empate com a segunda.</li>\n<li><strong>Outro produto…:</strong> escolha pelo código ou pelo nome.</li>\n<li><strong>＋ Criar produto:</strong> cria o produto com o nome, a categoria e a subcategoria escolhidos e já liga. Só aparece para quem também acessa Estoque → Produtos.</li>\n<li><strong>Não é item de locação:</strong> para o que não se aluga (cabo de configuração, material de uso interno).</li>\n<li><strong>Desfazer:</strong> volta o item para pendente.</li>\n</ul>\n<p>A &quot;qtd antiga&quot; é a contagem que existia no Controle de Estoque. Serve só de referência: a contagem que vale é a do inventário, em Equipamentos de Locação.</p>\n<h2 id=\"eventos-e-feiras\">Eventos e feiras</h2>\n<p><strong>Onde fica:</strong> Comercial → Eventos e Feiras, botão <strong>+ Novo evento</strong>. Clicar num evento da lista abre para editar.</p>\n<ul>\n<li><strong>Nome do evento</strong> e <strong>Data inicial</strong> são obrigatórios. Nome + data inicial não pode repetir.</li>\n<li><strong>Data final, local, montadora, promotor, tipo e responsável</strong> completam o cadastro.</li>\n<li><strong>Status:</strong> Futuro, Em Execução ou Finalizado segue as datas sozinho e é recalculado todo dia.</li>\n</ul>\n<p><span class=\"figura\"><img src=\"data:image/png;base64,\" alt=\"Novo evento / feira\" loading=\"lazy\" /><span class=\"legenda\">Novo evento / feira</span></span></p>\n<p>O evento cadastrado aqui já aparece no orçamento da locação e na Expedição, que sugere endereço e datas pelas fichas do sistema.</p>\n<h2 id=\"plano-de-contas-centros-e-sub-centros\">Plano de contas: centros e sub-centros</h2>\n<p><strong>Onde fica:</strong> OP → Natureza &amp; Classificação Financeira, painel <strong>Centros e sub-centros (plano de contas)</strong>. Clique no título para abrir.</p>\n<ul>\n<li><strong>Novo centro:</strong> número, nome e se é de Custo ou de Receita.</li>\n<li><strong>Novo sub-centro:</strong> escolha o centro, informe o código (ex.: 6.4) e o nome.</li>\n<li>Cada sub-centro novo já vira uma <strong>natureza da OP classificada</strong>, pronta para usar na Ordem de Pagamento.</li>\n</ul>\n<p><span class=\"figura\"><img src=\"data:image/png;base64,\" alt=\"OP → Natureza &amp; Classificação Financeira: painel de centros e sub-centros aberto\" loading=\"lazy\" /><span class=\"legenda\">OP → Natureza &amp; Classificação Financeira: painel de centros e sub-centros aberto</span></span></p>\n<p>Antes da virada, centros e sub-centros continuam vindo do P2S. Crie aqui só o que faltar no P2S.</p>\n<h2 id=\"vendedor-cliente-e-fornecedor-na-ficha-do-rh\">Vendedor, cliente e fornecedor na Ficha do RH</h2>\n<p><strong>Onde fica:</strong> RH → Ficha do Funcionário, aba Essencial, painel <strong>💼 Papéis comerciais</strong> (abaixo de &quot;Pode dirigir&quot;). O painel aparece depois que a ficha é salva pela primeira vez. Cada marcação <strong>grava na hora</strong>, sem depender do botão Salvar.</p>\n<p><span class=\"figura\"><img src=\"data:image/png;base64,\" alt=\"Ficha do RH com o painel Papéis comerciais: vendedor e cliente marcados\" loading=\"lazy\" /><span class=\"legenda\">Ficha do RH com o painel Papéis comerciais: vendedor e cliente marcados</span></span></p>\n<p>Abaixo das caixas, o painel mostra o cadastro de vendedor ligado (número e origem) e o parceiro achado pelo CPF.</p>\n<p><strong>Vendedor.</strong> Marcar liga a ficha ao cadastro de vendedor: o que já existe no P2S (pelo CPF, ou pelo nome quando não há CPF) ou um novo, criado pelo sistema. Carteira, comissões, fichas e o acesso usuário → vendedor usam esse cadastro.</p>\n<ul>\n<li>O RH manda: se o P2S mudar a marcação, a sincronização volta a aplicar a da ficha.</li>\n<li>Funcionário desligado vira vendedor inativo.</li>\n<li>Quando o P2S tem o mesmo CPF duas vezes (readmissão), vale o cadastro do vendedor, depois o ativo, depois o mais recente.</li>\n</ul>\n<p><strong>Cliente e fornecedor.</strong> O <strong>CPF da ficha é a chave</strong>, para nunca duplicar o cadastro.</p>\n<ul>\n<li>Sem um CPF válido salvo na ficha, as caixas ficam travadas.</li>\n<li>Se você mudou o CPF, salve a ficha antes de marcar.</li>\n<li>Se já existe um parceiro com aquele CPF, ele é usado. Se não existe, o sistema cria o cadastro com os dados da ficha (nome, endereço, celular e e-mail).</li>\n<li>Se o parceiro veio do P2S, enquanto o P2S for oficial a marcação de cliente ou fornecedor dele muda no P2S. O painel avisa.</li>\n<li>Desmarcar cliente não mexe em fornecedor, e vice-versa.</li>\n</ul>\n<h2 id=\"dúvidas-frequentes\">Dúvidas frequentes</h2>\n<p><strong>Cadastrei um cliente aqui e depois no P2S. Ficou duplicado?</strong> Não. Na sincronização, o cadastro do P2S com o mesmo CPF/CNPJ adota o daqui: fica um só, com o mesmo código.</p>\n<p><strong>O formulário não deixa editar o cliente.</strong> Ele veio do P2S e o P2S ainda é oficial. Altere lá; a carteira do vendedor dá para mudar aqui.</p>\n<p><strong>O vendedor não aparece na carteira nem nas comissões.</strong> Confira na Ficha do RH se a caixa Vendedor está marcada e se o funcionário está ativo.</p>\n<p><strong>As caixas de cliente e fornecedor estão travadas na Ficha do RH.</strong> Falta CPF válido na ficha. Preencha, salve e marque de novo.</p>\n<p><strong>Por que o centro que criei não aparece na OP?</strong> A OP usa a natureza. Use a natureza criada junto com o sub-centro: ela leva o nome do centro e do sub-centro (ex.: &quot;EQUIPAMENTOS — 6.4 TELEVISORES&quot;).</p>\n";
export const sumario: { id: string; texto: string }[] = [{"id":"visão-geral","texto":"Visão geral"},{"id":"antes-e-depois-da-virada","texto":"Antes e depois da virada"},{"id":"clientes-e-fornecedores","texto":"Clientes e fornecedores"},{"id":"produtos-e-equipamentos","texto":"Produtos e equipamentos"},{"id":"eventos-e-feiras","texto":"Eventos e feiras"},{"id":"plano-de-contas-centros-e-sub-centros","texto":"Plano de contas: centros e sub-centros"},{"id":"vendedor-cliente-e-fornecedor-na-ficha-do-rh","texto":"Vendedor, cliente e fornecedor na Ficha do RH"},{"id":"dúvidas-frequentes","texto":"Dúvidas frequentes"}];
